import sys

def pos(s, a, b, c, k):
    ret = 0
    for x in s:
        if x == 'V':
            if a == 0:
                if k == 0:
                    return ret
                ret += 1
            else:
                a -= 1
        elif x == 'K':
            if b == 0:
                if k == 1:
                    return ret
                ret += 1
            else:
                b -= 1
        else:
            if c == 0:
                if k == 2:
                    return ret
                ret += 1
            else:
                c -= 1
    return -1

