    input = sys.stdin.read().splitlines()
    n = int(input[0].strip())
    s = list(input[1])

    import math
    dp = [[[[math.inf for _ in range(n+1)] for _ in range(n+1)] for _ in range(n+1)] for _ in range(3)]
    vTotal = s.count('V')
    kTotal = s.count('K')
    eTotal = s.count('E') if 'E' in s else s.count('')  # fallback if no 'E', but original code assumes only V, K, and others
    # Since original code only checks for 'V', 'K', and else, assume 'E' is any other character
    # For safety, count all characters not 'V' or 'K' as 'E'
    eTotal = len([x for x in s if x != 'V' and x != 'K'])

    # Initialize the DP
    dp[2][0][0][0] = 0

    # Precompute poss array
    poss = [[[ [0 for _ in range(n+1)] for _ in range(kTotal+1)] for _ in range(vTotal+1)] for _ in range(3)]
    for i in range(vTotal+1):
        for j in range(kTotal+1):
            for k in range(eTotal+1):
                for l in range(3):
                    poss[l][i][j][k] = pos(s, i, j, k, l)

    for i in range(vTotal+1):
        for j in range(kTotal+1):
            for k in range(eTotal+1):
                for l in range(3):
                    if i + 1 <= vTotal and poss[0][i][j][k] != -1:
                        v = poss[0][i][j][k]
                        if dp[2][i][j][k] != math.inf:
                            dp[0][i + 1][j][k] = min(dp[0][i + 1][j][k], dp[2][i][j][k] + v)
                        if dp[1][i][j][k] != math.inf:
                            dp[0][i + 1][j][k] = min(dp[0][i + 1][j][k], dp[1][i][j][k] + v)
                        if dp[0][i][j][k] != math.inf:
                            dp[0][i + 1][j][k] = min(dp[0][i + 1][j][k], dp[0][i][j][k] + v)
                    if j + 1 <= kTotal and poss[1][i][j][k] != -1:
                        v = poss[1][i][j][k]
                        if dp[2][i][j][k] != math.inf:
                            dp[1][i][j + 1][k] = min(dp[1][i][j + 1][k], dp[2][i][j][k] + v)
                        if dp[1][i][j][k] != math.inf:
                            dp[1][i][j + 1][k] = min(dp[1][i][j + 1][k], dp[1][i][j][k] + v)
                    if k + 1 <= eTotal and poss[2][i][j][k] != -1:
                        v = poss[2][i][j][k]
                        if dp[2][i][j][k] != math.inf:
                            dp[2][i][j][k + 1] = min(dp[2][i][j][k + 1], dp[2][i][j][k] + v)
                        if dp[1][i][j][k] != math.inf:
                            dp[2][i][j][k + 1] = min(dp[2][i][j][k + 1], dp[1][i][j][k] + v)
                        if dp[0][i][j][k] != math.inf:
                            dp[2][i][j][k + 1] = min(dp[2][i][j][k + 1], dp[0][i][j][k] + v)
    result = min(dp[0][vTotal][kTotal][eTotal], dp[1][vTotal][kTotal][eTotal], dp[2][vTotal][kTotal][eTotal])
    print(result)

